// --- INFORMACOES DA RACA ---
std::string Troll::getRaceName() const 
{ 
    return "Troll"; 
}

Attributes Troll::getRaceAttributes() const 
{ 
    return { 500, 20, 1, 10, 10, 0, 0 }; // health, strength, dexterity, resistance, constitution, intelligence, wisdom
}

std::vector<std::unique_ptr<Item>> Troll::getRaceEquipment() const 
{
    std::vector<std::unique_ptr<Item>> equipamentos;
    equipamentos.push_back(ItemFactory::criarItem(ItemID::TroncoAmarrotado));
    return equipamentos;
}

// --- HABILIDADE DA RACA ---
std::string Troll::getRaceAbilityName() const { return "Regeneracao Troll"; }
std::string Troll::getRaceAbilityDescription() const { return "Pele aspera e capacidade de regenerar as feridas mais brutais. (Boss)"; }

